unitTests:
TEST("boiling point") { CHECK_NEAR(celsiusToFahrenheit(100.0), 212.0, 0.0001); }
TEST("freezing point") { CHECK_NEAR(celsiusToFahrenheit(0.0), 32.0, 0.0001); }
TEST("body temperature") { CHECK_NEAR(celsiusToFahrenheit(37.0), 98.6, 0.0001); }
TEST("minus forty is the same in both") { CHECK_NEAR(celsiusToFahrenheit(-40.0), -40.0, 0.0001); }

